export const EXPECTED_LINKAGE_INTERVAL_CONSTRUCTION_METRICS = Object.freeze({"world_count":8,"distinct_public_status_signatures":1,"distinct_interval_construction_governance_signatures":8,"complete_linkage_interval_construction_assurance_worlds":1,"undefined_target_pairs":100,"in_sample_interval_pairs":40,"calibration_validation_overlap_pairs":40,"dependence_invalidated_pairs":40,"cluster_leaked_pairs":30,"invalid_resampling_pairs":30,"effective_sample_size_overstatement":60,"multiplicity_uncorrected_pairs":40,"adaptively_selected_pairs":30,"optional_stopping_contaminated_pairs":30,"simultaneous_coverage_unsupported_pairs":50,"denominator_excluded_pairs":50,"omitted_hard_negatives":20,"omitted_unlabelled_pairs":20,"stale_interval_decisions":100,"unsupported_interval_decisions":700,"binding_public_authority_worlds":0});

const object = value => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const array = value => Array.isArray(value) ? value : [];
const text = value => String(value ?? '').trim();
const unique = values => [...new Set(array(values).map(text).filter(Boolean))];
const sorted = values => [...values].sort((left, right) => String(left).localeCompare(String(right)));
const canonical = value => Array.isArray(value) ? value.map(canonical) : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;
const stable = value => JSON.stringify(canonical(value));
const sha256 = value => createHash('sha256').update(stable(value)).digest('hex');
const sameMembers = (left, right) => stable(sorted(unique(left))) === stable(sorted(unique(right)));
const requireFalse = (value, label, errors) => { if (value !== false) errors.push(`${label} must remain false`); };
const allTrue = (source, keys) => keys.every(key => source?.[key] === true);
const allZero = (source, keys) => keys.every(key => source?.[key] === 0);
function seal(event, previous) { const unsigned = { ...canonical(event), previous_event_sha256: previous }; return { ...unsigned, event_sha256: sha256(unsigned) }; }

function deriveFlags(world) {
  const target = object(world?.target_construction);
  const separation = object(world?.data_separation);
  const dependence = object(world?.dependence_resampling);
  const multiplicity = object(world?.multiplicity_selection);
  const coverage = object(world?.empirical_coverage);
  const governance = object(world?.governance);
  const completeTarget = allTrue(target, ['target_event_defined','estimand_defined','coverage_meaning_defined','interval_type_valid','construction_method_predeclared','construction_method_current','exchangeability_assumption_stated','distribution_shift_bounded']) && allZero(target, ['undefined_target_pairs','in_sample_interval_pairs']);
  const completeSeparation = allTrue(separation, ['training_construction_separate','tuning_construction_separate','calibration_validation_separate','construction_holdout_separate','deployment_validation_separate','independent_labels_complete']) && allZero(separation, ['calibration_validation_overlap_pairs']);
  const completeDependence = allTrue(dependence, ['entity_block_split_safe','source_block_split_safe','temporal_block_split_safe','cluster_graph_trajectory_dependence_preserved','resampling_unit_correct','covariance_model_current','effective_sample_size_valid']) && allZero(dependence, ['dependence_invalidated_pairs','cluster_leaked_pairs','invalid_resampling_pairs','effective_sample_size_overstatement']);
  const completeMultiplicity = allTrue(multiplicity, ['family_predeclared','model_threshold_subgroup_window_family_complete','adaptive_selection_accounted','repeated_looks_corrected','optional_stopping_accounted','winner_selection_corrected','simultaneous_coverage_supported']) && allZero(multiplicity, ['multiplicity_uncorrected_pairs','adaptively_selected_pairs','optional_stopping_contaminated_pairs','simultaneous_coverage_unsupported_pairs']);
  const completeCoverage = allTrue(coverage, ['target_population_denominator_complete','labelled_unlabelled_denominator_complete','hard_negatives_included','weak_sources_missingness_included','sampling_weights_current','confidence_bounds_complete','miss_root_causes_audited','subgroup_source_time_coverage_complete']) && allZero(coverage, ['denominator_excluded_pairs','omitted_hard_negatives','omitted_unlabelled_pairs']);
  const currentLineage = allTrue(governance, ['current_lineage','negative_controls_complete','falsification_complete','correction_complete','certificate_current','public_claim_supported']) && governance.binding_public_authority === false && allZero(governance, ['stale_interval_decisions','unsupported_interval_decisions']);
  return {
    complete_target_and_construction_assurance: completeTarget,
    complete_data_separation_assurance: completeSeparation,
    complete_dependence_and_resampling_assurance: completeDependence,
    complete_multiplicity_and_simultaneous_coverage_assurance: completeMultiplicity,
    complete_empirical_denominator_and_coverage_assurance: completeCoverage,
    current_interval_lineage_assurance: currentLineage,
    binding_public_authority_supported: false,
    real_world_effect_claimed: false,
    graph_effect_present: false,
    preference_change_present: false,
    complete_linkage_interval_construction_assurance: completeTarget && completeSeparation && completeDependence && completeMultiplicity && completeCoverage && currentLineage
  };
}

function custodyChain(fixture, world, flags, publicSignature, governanceSignature) {
  const events = []; let previous = null;
  const push = event => { const sealed = seal(event, previous); events.push(sealed); previous = sealed.event_sha256; };
  const prefix = `${fixture.fixture_id}:${world.world_id}`;
  push({ event_id:`${prefix}:public`, event_type:'linkage_interval_publication_surface_frozen', evidence_class:'synthetic_public_claim_surface', authority:'pc45_fixture_compiler', source_event_ids:[], payload:{ baseline:fixture.baseline, public_status_signature_sha256:publicSignature } });
  push({ event_id:`${prefix}:target`, event_type:'target_estimand_and_interval_construction_state', evidence_class:'synthetic_interval_construction_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:public`], payload:world.target_construction });
  push({ event_id:`${prefix}:separation`, event_type:'construction_calibration_validation_and_label_separation_state', evidence_class:'synthetic_data_lineage_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:target`], payload:world.data_separation });
  push({ event_id:`${prefix}:dependence`, event_type:'dependence_resampling_and_effective_sample_size_state', evidence_class:'synthetic_dependence_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:separation`], payload:world.dependence_resampling });
  push({ event_id:`${prefix}:multiplicity`, event_type:'multiplicity_adaptive_selection_and_simultaneous_coverage_state', evidence_class:'synthetic_selection_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:dependence`], payload:world.multiplicity_selection });
  push({ event_id:`${prefix}:coverage`, event_type:'empirical_coverage_denominator_and_exclusion_state', evidence_class:'synthetic_coverage_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:multiplicity`], payload:world.empirical_coverage });
  push({ event_id:`${prefix}:governance`, event_type:'interval_lineage_correction_certificate_and_authority_state', evidence_class:'synthetic_governance_state', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:coverage`], payload:world.governance });
  push({ event_id:`${prefix}:flags`, event_type:'linkage_interval_construction_assurance_flags_derived', evidence_class:'derived_synthetic_classification', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:governance`], payload:flags });
  push({ event_id:`${prefix}:mechanism`, event_type:'linkage_interval_construction_mechanism_classified', evidence_class:'synthetic_mechanism_classification', authority:'pc45_fixture_compiler', source_event_ids:[`${prefix}:flags`], payload:{ mechanism:world.expected_mechanism, interval_construction_governance_signature_sha256:governanceSignature } });
  return events;
}

function metricsFor(worlds) {
  const sum = (section, key) => worlds.reduce((total, world) => total + Number(world?.[section]?.[key] ?? 0), 0);
  return {
    world_count: worlds.length,
    distinct_public_status_signatures: new Set(worlds.map(world => world.public_status_signature_sha256)).size,
    distinct_interval_construction_governance_signatures: new Set(worlds.map(world => world.interval_construction_governance_signature_sha256)).size,
    complete_linkage_interval_construction_assurance_worlds: worlds.filter(world => world.flags.complete_linkage_interval_construction_assurance).length,
    undefined_target_pairs: sum('target_construction','undefined_target_pairs'),
    in_sample_interval_pairs: sum('target_construction','in_sample_interval_pairs'),
    calibration_validation_overlap_pairs: sum('data_separation','calibration_validation_overlap_pairs'),
    dependence_invalidated_pairs: sum('dependence_resampling','dependence_invalidated_pairs'),
    cluster_leaked_pairs: sum('dependence_resampling','cluster_leaked_pairs'),
    invalid_resampling_pairs: sum('dependence_resampling','invalid_resampling_pairs'),
    effective_sample_size_overstatement: sum('dependence_resampling','effective_sample_size_overstatement'),
    multiplicity_uncorrected_pairs: sum('multiplicity_selection','multiplicity_uncorrected_pairs'),
    adaptively_selected_pairs: sum('multiplicity_selection','adaptively_selected_pairs'),
    optional_stopping_contaminated_pairs: sum('multiplicity_selection','optional_stopping_contaminated_pairs'),
    simultaneous_coverage_unsupported_pairs: sum('multiplicity_selection','simultaneous_coverage_unsupported_pairs'),
    denominator_excluded_pairs: sum('empirical_coverage','denominator_excluded_pairs'),
    omitted_hard_negatives: sum('empirical_coverage','omitted_hard_negatives'),
    omitted_unlabelled_pairs: sum('empirical_coverage','omitted_unlabelled_pairs'),
    stale_interval_decisions: sum('governance','stale_interval_decisions'),
    unsupported_interval_decisions: sum('governance','unsupported_interval_decisions'),
    binding_public_authority_worlds: worlds.filter(world => world.governance.binding_public_authority === true).length
  };
}

export function validatePreferenceLinkageIntervalConstructionAssuranceFixture(fixture) {
  const errors = [];
  if (fixture?.schema_version !== PREFERENCE_LINKAGE_INTERVAL_CONSTRUCTION_ASSURANCE_FIXTURE_SCHEMA_VERSION) errors.push('fixture schema mismatch');
  if (fixture?.fixture_id !== 'same-linkage-interval-validated-status-different-construction-states-v1' || fixture?.issue !== 978 || fixture?.parent_program_issue !== 594) errors.push('fixture identity or issue lineage mismatch');
  if (fixture?.status !== 'synthetic_control' || fixture?.graph_effect !== 'none') errors.push('fixture status or graph effect mismatch');
  requireFalse(fixture?.counts_toward_thesis_evidence, 'fixture thesis evidence', errors);
  if (stable(fixture?.baseline) !== stable(BASELINE)) errors.push('fixture public surface mismatch');
  if (!sameMembers(fixture?.required_refusal_rules, REQUIRED_REFUSAL_RULES) || array(fixture?.required_refusal_rules).length !== REQUIRED_REFUSAL_RULES.length) errors.push('fixture refusal-rule ledger mismatch');
  if (stable(fixture?.expected_classification) !== stable(EXPECTED_CLASSIFICATION)) errors.push('fixture classification contract mismatch');
  const worlds = array(fixture?.worlds);
  if (worlds.length !== 8 || !sameMembers(worlds.map(world => world?.world_id), EXPECTED_WORLD_IDS)) errors.push('fixture world denominator mismatch');
  for (const world of worlds) {
    const id = text(world?.world_id); const expected = WORLD_EXPECTATIONS.get(id);
    if (!expected) { errors.push(`unexpected world: ${id || '<blank>'}`); continue; }
    if (stable(world) !== stable(expected)) errors.push(`${id} world contract mismatch`);
    const flags = deriveFlags(world);
    if (stable(flags) !== stable(world.expected_flags)) errors.push(`${id} expected flags mismatch`);
    if (world?.governance?.binding_public_authority !== false) errors.push(`${id} binding public authority must remain false`);
  }
  const complete = worlds.filter(world => deriveFlags(world).complete_linkage_interval_construction_assurance);
  if (complete.length !== 1 || complete[0]?.world_id !== EXPECTED_WORLD_IDS[0]) errors.push('exactly one complete linkage-interval construction assurance world is required');
  return errors;
}

export function compilePreferenceLinkageIntervalConstructionAssuranceFixture(fixture) {
  const errors = validatePreferenceLinkageIntervalConstructionAssuranceFixture(fixture);
  if (errors.length) throw new Error(`invalid linkage-interval construction fixture:\n- ${errors.join('\n- ')}`);
  const publicSignature = sha256(fixture.baseline);
  const worlds = fixture.worlds.map(source => {
    const world = canonical(source); const flags = deriveFlags(world);
    const provenance = { target_construction:world.target_construction, data_separation:world.data_separation, dependence_resampling:world.dependence_resampling, multiplicity_selection:world.multiplicity_selection, empirical_coverage:world.empirical_coverage, governance:world.governance };
    const governanceSignature = sha256(provenance);
    const chain = custodyChain(fixture, world, flags, publicSignature, governanceSignature);
    return { world_id:world.world_id, description:world.description, target_construction:world.target_construction, data_separation:world.data_separation, dependence_resampling:world.dependence_resampling, multiplicity_selection:world.multiplicity_selection, empirical_coverage:world.empirical_coverage, governance:world.governance, flags, mechanism:world.expected_mechanism, public_status_signature_sha256:publicSignature, interval_construction_governance_signature_sha256:governanceSignature, custody_chain:chain, custody_chain_head_sha256:chain.at(-1).event_sha256 };
  });
  return { schema_version:PREFERENCE_LINKAGE_INTERVAL_CONSTRUCTION_ASSURANCE_BUILD_SCHEMA_VERSION, fixture_id:fixture.fixture_id, issue:fixture.issue, parent_program_issue:fixture.parent_program_issue, captured_at:fixture.captured_at, status:'synthetic_linkage_interval_construction_control_qualified', graph_effect:'none', counts_toward_thesis_evidence:false, conclusion_generated:false, baseline:canonical(fixture.baseline), required_refusal_rules:[...fixture.required_refusal_rules], fixture_sha256:sha256(fixture), worlds, metrics:metricsFor(worlds), classification:{...fixture.expected_classification} };
}

function validateChain(world, errors) {
  const expectedTypes = ['linkage_interval_publication_surface_frozen','target_estimand_and_interval_construction_state','construction_calibration_validation_and_label_separation_state','dependence_resampling_and_effective_sample_size_state','multiplicity_adaptive_selection_and_simultaneous_coverage_state','empirical_coverage_denominator_and_exclusion_state','interval_lineage_correction_certificate_and_authority_state','linkage_interval_construction_assurance_flags_derived','linkage_interval_construction_mechanism_classified'];
  const chain = array(world?.custody_chain);
  if (chain.length !== expectedTypes.length) errors.push(`${world?.world_id} custody chain length mismatch`);
  let previous = null; const seen = new Set();
  for (let index = 0; index < chain.length; index += 1) {
    const event = chain[index];
    if (event?.event_type !== expectedTypes[index]) errors.push(`${world?.world_id} custody event type mismatch at ${index}`);
    if (event?.previous_event_sha256 !== previous) errors.push(`${world?.world_id} custody previous hash mismatch`);
    for (const sourceId of array(event?.source_event_ids)) if (!seen.has(sourceId)) errors.push(`${world?.world_id} custody source missing: ${sourceId}`);
    const unsigned = { ...event }; delete unsigned.event_sha256;
    if (event?.event_sha256 !== sha256(unsigned)) errors.push(`${world?.world_id} custody hash mismatch`);
    if (text(event?.event_id)) seen.add(event.event_id); previous = event?.event_sha256;
  }
  if (previous !== world?.custody_chain_head_sha256) errors.push(`${world?.world_id} custody head mismatch`);
}

export function validatePreferenceLinkageIntervalConstructionAssuranceBuild(build, fixture) {
  const errors = [];
  if (build?.schema_version !== PREFERENCE_LINKAGE_INTERVAL_CONSTRUCTION_ASSURANCE_BUILD_SCHEMA_VERSION) errors.push('build schema mismatch');
  if (build?.fixture_id !== 'same-linkage-interval-validated-status-different-construction-states-v1' || build?.issue !== 978 || build?.parent_program_issue !== 594) errors.push('build identity or issue lineage mismatch');
  if (build?.status !== 'synthetic_linkage_interval_construction_control_qualified' || build?.graph_effect !== 'none') errors.push('build status or graph effect mismatch');
  requireFalse(build?.counts_toward_thesis_evidence, 'build thesis evidence', errors); requireFalse(build?.conclusion_generated, 'build conclusion', errors);
  if (stable(build?.baseline) !== stable(BASELINE)) errors.push('build public surface mismatch');
  if (!sameMembers(build?.required_refusal_rules, REQUIRED_REFUSAL_RULES) || array(build?.required_refusal_rules).length !== REQUIRED_REFUSAL_RULES.length) errors.push('build refusal-rule ledger mismatch');
  if (!/^[0-9a-f]{64}$/.test(text(build?.fixture_sha256))) errors.push('build fixture hash invalid');
  if (!fixture) errors.push('build fixture source is required');
  else {
    const fixtureErrors = validatePreferenceLinkageIntervalConstructionAssuranceFixture(fixture);
    if (fixtureErrors.length) errors.push(...fixtureErrors.map(error => `build fixture source invalid: ${error}`));
    else {
      if (build?.fixture_sha256 !== sha256(fixture)) errors.push('build fixture hash does not match supplied fixture');
      const expectedBuild = compilePreferenceLinkageIntervalConstructionAssuranceFixture(fixture);
      if (stable(build) !== stable(expectedBuild)) errors.push('build does not deterministically reconstruct from supplied fixture');
    }
  }
  const worlds = array(build?.worlds);
  if (worlds.length !== 8 || !sameMembers(worlds.map(world => world?.world_id), EXPECTED_WORLD_IDS)) errors.push('build world denominator mismatch');
  for (const world of worlds) {
    const expected = WORLD_EXPECTATIONS.get(text(world?.world_id));
    if (!expected) { errors.push(`build unexpected world: ${text(world?.world_id) || '<blank>'}`); continue; }
    for (const section of ['target_construction','data_separation','dependence_resampling','multiplicity_selection','empirical_coverage','governance']) if (stable(world?.[section]) !== stable(expected[section])) errors.push(`${world.world_id} build ${section} mismatch`);
    const flags = deriveFlags(world);
    if (stable(world?.flags) !== stable(flags)) errors.push(`${world.world_id} build flags mismatch`);
    if (world?.mechanism !== expected.expected_mechanism) errors.push(`${world.world_id} mechanism mismatch`);
    if (world?.public_status_signature_sha256 !== sha256(BASELINE)) errors.push(`${world.world_id} public signature mismatch`);
    const provenance = { target_construction:world.target_construction, data_separation:world.data_separation, dependence_resampling:world.dependence_resampling, multiplicity_selection:world.multiplicity_selection, empirical_coverage:world.empirical_coverage, governance:world.governance };
    if (world?.interval_construction_governance_signature_sha256 !== sha256(provenance)) errors.push(`${world.world_id} governance signature mismatch`);
    if (world?.governance?.binding_public_authority !== false) errors.push(`${world.world_id} build authority leak`);
    validateChain(world, errors);
  }
  for (const [key, expected] of Object.entries(EXPECTED_LINKAGE_INTERVAL_CONSTRUCTION_METRICS)) if (build?.metrics?.[key] !== expected) errors.push(`metric mismatch: ${key}`);
  for (const key of LINKAGE_INTERVAL_CONSTRUCTION_FALSE_CLASSIFICATIONS) requireFalse(build?.classification?.[key], `classification.${key}`, errors);
  if (build?.classification?.[COMPLETE_LINKAGE_INTERVAL_CONSTRUCTION_CLASSIFICATION] !== true) errors.push('build complete assurance path missing');
  return errors;
}

export function renderPreferenceLinkageIntervalConstructionAssuranceMarkdown(build) {
  const lines = ['# Linkage interval construction, dependence, multiplicity, and empirical coverage assurance','',`**Status:** ${build.status}`,'',`**Worlds:** ${build.metrics.world_count}`,'',`**Public status signatures:** ${build.metrics.distinct_public_status_signatures}`,'',`**Construction-governance signatures:** ${build.metrics.distinct_interval_construction_governance_signatures}`,'','> One nominal or published empirical coverage headline does not identify a defined interval target, out-of-sample construction, dependence-aware resampling, effective sample size, multiplicity correction, simultaneous coverage, complete empirical denominator, or current lineage.','','## Deterministic burden surface',''];
  for (const [key, value] of Object.entries(build.metrics)) lines.push(`- ${key}: ${value}`);
  lines.push('', '## Worlds', ''); for (const world of build.worlds) lines.push(`- **${world.world_id}** — ${world.mechanism}`);
  lines.push('', '## Claim boundary', '', 'This synthetic control creates no real identity map, interval, empirical coverage rate, target-population burden, causal conclusion, graph effect, or public-authority verdict.');
  return `${lines.join('\n')}\n`;
}
